def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    for dc in (-1, 1):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue
                # Only begin at the first cell of a contiguous diagonal run.
                pr, pc = r - 1, c - dc
                if pr >= 0 and 0 <= pc < w and grid[pr][pc] == color:
                    continue

                run = []
                rr, cc = r, c
                while rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr, cc))
                    rr += 1
                    cc += dc
                if len(run) < 2:
                    continue

                # Extend both ends of this diagonal run, stopping at any obstacle.
                rr, cc = run[-1][0] + 1, run[-1][1] + dc
                while rr < h and 0 <= cc < w and out[rr][cc] == bg:
                    out[rr][cc] = color
                    rr += 1
                    cc += dc

                rr, cc = run[0][0] - 1, run[0][1] - dc
                while rr >= 0 and 0 <= cc < w and out[rr][cc] == bg:
                    out[rr][cc] = color
                    rr -= 1
                    cc -= dc
    return out
